// repi.c: incremental exact t=5 binary repair, 2 threads. Maintains hole list, unique-event list, and cellU[r][c]
// (number of unique events with row r containing column c). A flip (r,c) only touches events that contain c and whose other
// 4 values equal row r's; those are regenerated by one tree enumeration over r-agreeing rows.
// usage: repi FILE seed T MAXFLIPS out [ncols_trunc(0=all)] ; env THREADS (default 2), CHECK=1 (verify vs full scan), MAXIT
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <pthread.h>
#define MAXN 384
#define RW 6
#define CW 3
typedef struct {int16_t c[5]; uint8_t v[5]; int row;} Ev;
typedef struct {Ev*a; int n,cap;} Vec;
static void vpush(Vec*v,Ev e){ if(v->n==v->cap){v->cap=v->cap?v->cap*2:1024;v->a=realloc(v->a,v->cap*sizeof(Ev));} v->a[v->n++]=e;}
static int N,K;
static uint8_t A[MAXN][192];
static uint64_t rowb[MAXN][CW];   // row bits over columns
static uint64_t colb[192][RW];    // column bits over rows
static Vec U,Hs; static int *cellU;
static uint64_t rs; static inline uint64_t rnd(){rs^=rs<<13;rs^=rs>>7;rs^=rs<<17;return rs;}
static inline double ur(){return (rnd()>>11)*(1.0/9007199254740992.0);}
static void setbit(int r,int c,int v){ if(v){rowb[r][c>>6]|=1ULL<<(c&63);colb[c][r>>6]|=1ULL<<(r&63);A[r][c]=1;} else {rowb[r][c>>6]&=~(1ULL<<(c&63));colb[c][r>>6]&=~(1ULL<<(r&63));A[r][c]=0;} }
// ---- enumeration for flip of (r,c): call after A updated. Generates events with column c and other 4 cols from tree.
typedef struct {int r,c,nv,old,tid,nth; Vec out; uint64_t ag[192][RW]; uint64_t Mo[RW],Mn[RW]; } Job;
static uint64_t gt[192][CW];
static void enumjob(Job*J){
  int r=J->r,c=J->c,old=J->old,nv=J->nv;
  int cols[192],nc=0; for(int i=0;i<K;i++) if(i!=c) cols[nc++]=i;
  uint64_t validc[CW]; for(int w=0;w<CW;w++) validc[w]=~0ULL; validc[c>>6]&=~(1ULL<<(c&63)); if(K<192){ for(int w=0;w<CW;w++){ for(int b=0;b<64;b++) if(w*64+b>=K) validc[w]&=~(1ULL<<b);} }
  for(int i2x=J->tid;i2x<nc;i2x+=J->nth){
    int i2=cols[i2x]; uint64_t Mo2[RW],Mn2[RW]; for(int w=0;w<RW;w++){Mo2[w]=J->Mo[w]&J->ag[i2][w];Mn2[w]=J->Mn[w]&J->ag[i2][w];}
    for(int i3x=i2x+1;i3x<nc;i3x++){ int i3=cols[i3x]; uint64_t Mo3[RW],Mn3[RW]; for(int w=0;w<RW;w++){Mo3[w]=Mo2[w]&J->ag[i3][w];Mn3[w]=Mn2[w]&J->ag[i3][w];}
      for(int i4x=i3x+1;i4x<nc-1;i4x++){ int i4=cols[i4x]; uint64_t Mo4[RW],Mn4[RW]; for(int w=0;w<RW;w++){Mo4[w]=Mo3[w]&J->ag[i4][w];Mn4[w]=Mn3[w]&J->ag[i4][w];}
        uint64_t o1[CW]={0},t1[CW]={0},n1[CW]={0};
        for(int w=0;w<RW;w++){uint64_t m=Mo4[w];while(m){int b=__builtin_ctzll(m);m&=m-1;int t=w*64+b;
            for(int k=0;k<CW;k++){uint64_t x=~(rowb[t][k]^rowb[r][k]);t1[k]|=o1[k]&x;o1[k]|=x;}}
          m=Mn4[w];while(m){int b=__builtin_ctzll(m);m&=m-1;int t=w*64+b;
            for(int k=0;k<CW;k++){uint64_t x=~(rowb[t][k]^rowb[r][k]);n1[k]|=x;}}}
        for(int k=0;k<CW;k++){
          uint64_t vm=validc[k]&gt[i4][k]; if(!vm) continue;
          uint64_t hole=~o1[k]&vm, uni=o1[k]&~t1[k]&vm, nu=~n1[k]&vm;
          uint64_t all=hole|uni|nu;
          while(all){int b=__builtin_ctzll(all);all&=all-1;int d=k*64+b; uint64_t bm=1ULL<<b;
            Ev e; e.c[0]=c;e.c[1]=i2;e.c[2]=i3;e.c[3]=i4;e.c[4]=d; e.v[1]=A[r][i2];e.v[2]=A[r][i3];e.v[3]=A[r][i4];e.v[4]=A[r][d];
            if(hole&bm){e.v[0]=old;e.row=-1;vpush(&J->out,e);}
            if(uni&bm){e.v[0]=old;int rr=-1;for(int w=0;w<RW&&rr<0;w++){uint64_t m=Mo4[w];while(m){int bb=__builtin_ctzll(m);m&=m-1;int t=w*64+bb;if(A[t][d]==A[r][d]){rr=t;break;}}}e.row=rr;vpush(&J->out,e);}
            if(nu&bm){e.v[0]=nv;e.row=r;vpush(&J->out,e);}
          }
        }
      }}}
}
static void *thr(void*p){enumjob((Job*)p);return 0;}
static int THREADS=2;
static void addev(Ev e){ if(e.row<0) vpush(&Hs,e); else {vpush(&U,e); for(int j=0;j<5;j++)cellU[e.row*K+e.c[j]]++;} }
static void filt(Vec*V,int r,int c,int isU){ int j=0; for(int i=0;i<V->n;i++){Ev*e=&V->a[i]; int ic=-1; for(int q=0;q<5;q++) if(e->c[q]==c){ic=q;break;}
    int kill=0; if(ic>=0){kill=1; for(int q=0;q<5;q++) if(q!=ic && e->v[q]!=A[r][e->c[q]]){kill=0;break;}}
    if(kill){ if(isU) for(int q=0;q<5;q++) cellU[e->row*K+e->c[q]]--; } else V->a[j++]=*e; }
  V->n=j; }
static Job *jobs[8];
static void flip(int r,int c){
  int old=A[r][c],nv=1-old;
  filt(&U,r,c,1); filt(&Hs,r,c,0);
  setbit(r,c,nv);
  static Job J[8]; static int init=0; if(!init){init=1;for(int i=0;i<8;i++){memset(&J[i],0,sizeof(Job));}}
  uint64_t Mo[RW],Mn[RW];
  for(int w=0;w<RW;w++){uint64_t cb=colb[c][w]; Mo[w]=old?cb:~cb; Mn[w]=old?~cb:cb;}
  for(int w=0;w<RW;w++){ uint64_t valid=~0ULL; for(int b=0;b<64;b++) if(w*64+b>=N) valid&=~(1ULL<<b); Mo[w]&=valid; Mn[w]&=valid; }
  Mo[r>>6]&=~(1ULL<<(r&63)); Mn[r>>6]&=~(1ULL<<(r&63));
  static uint64_t ag[192][RW];
  for(int d=0;d<K;d++) for(int w=0;w<RW;w++){uint64_t cb=colb[d][w]; ag[d][w]= A[r][d]?cb:~cb;}
  pthread_t th[8];
  for(int i=0;i<THREADS;i++){ Job*j=&J[i]; j->r=r;j->c=c;j->nv=nv;j->old=old;j->tid=i;j->nth=THREADS;j->out.n=0; memcpy(j->Mo,Mo,sizeof Mo);memcpy(j->Mn,Mn,sizeof Mn); memcpy(j->ag,ag,sizeof ag);}
  for(int i=1;i<THREADS;i++) pthread_create(&th[i],0,thr,&J[i]);
  enumjob(&J[0]);
  for(int i=1;i<THREADS;i++) pthread_join(th[i],0);
  for(int i=0;i<THREADS;i++) for(int q=0;q<J[i].out.n;q++) addev(J[i].out.a[q]);
}
// ---- full scan (reference, simple): enumerate 5-sets, patterns; used for init and CHECK. slow but exact: rows partition tree.
typedef struct {int tid,nth; Vec out;} FJ;
static void *fthr(void*p){ FJ*J=p;
  static __thread int l0[2][MAXN]; 
  for(int c0=J->tid;c0<K;c0+=J->nth){
    int m0[2]={0,0}; for(int r=0;r<N;r++){int b=A[r][c0]; l0[b][m0[b]++]=r;}
    for(int b=0;b<2;b++) for(int i2=c0+1;i2<K;i2++){
      int l2[2][MAXN],m2[2]={0,0}; for(int q=0;q<m0[b];q++){int r=l0[b][q];int x=A[r][i2];l2[x][m2[x]++]=r;}
      for(int b2=0;b2<2;b2++) for(int i3=i2+1;i3<K;i3++){
        int l3[2][MAXN],m3[2]={0,0}; for(int q=0;q<m2[b2];q++){int r=l2[b2][q];int x=A[r][i3];l3[x][m3[x]++]=r;}
        for(int b3=0;b3<2;b3++) for(int i4=i3+1;i4<K-1;i4++){
          int l4[2][MAXN],m4[2]={0,0}; for(int q=0;q<m3[b3];q++){int r=l3[b3][q];int x=A[r][i4];l4[x][m4[x]++]=r;}
          for(int b4=0;b4<2;b4++){ int *rows=l4[b4]; int mm=m4[b4];
            uint64_t o1[CW]={0},t1[CW]={0},o0[CW]={0},t0[CW]={0};
            for(int q=0;q<mm;q++){uint64_t*w=rowb[rows[q]];for(int k=0;k<CW;k++){uint64_t x=w[k];t1[k]|=o1[k]&x;o1[k]|=x;uint64_t y=~x;t0[k]|=o0[k]&y;o0[k]|=y;}}
            for(int k=0;k<CW;k++){ uint64_t vm=gt[i4][k]; if(!vm)continue;
              for(int bit=0;bit<2;bit++){ uint64_t once=bit?o1[k]:o0[k],twice=bit?t1[k]:t0[k];
                uint64_t all=(~once|(once&~twice))&vm;
                while(all){int bi=__builtin_ctzll(all);all&=all-1;int d=k*64+bi;Ev e;e.c[0]=c0;e.c[1]=i2;e.c[2]=i3;e.c[3]=i4;e.c[4]=d;
                  e.v[0]=b;e.v[1]=b2;e.v[2]=b3;e.v[3]=b4;e.v[4]=bit;e.row=-1;
                  if((once>>bi)&1){ for(int q=0;q<mm;q++) if(A[rows[q]][d]==bit){e.row=rows[q];break;} }
                  vpush(&J->out,e);} } }
          }}}}}
  return 0;}
static void fullscan(){
  U.n=0;Hs.n=0;memset(cellU,0,sizeof(int)*N*K);
  FJ J[8]; pthread_t th[8]; for(int i=0;i<THREADS;i++){J[i].tid=i;J[i].nth=THREADS;J[i].out.a=0;J[i].out.n=J[i].out.cap=0;}
  for(int i=1;i<THREADS;i++)pthread_create(&th[i],0,fthr,&J[i]); fthr(&J[0]); for(int i=1;i<THREADS;i++)pthread_join(th[i],0);
  for(int i=0;i<THREADS;i++){for(int q=0;q<J[i].out.n;q++)addev(J[i].out.a[q]);free(J[i].out.a);}
}
static int cmpev(const void*a,const void*b){const Ev*x=a,*y=b; for(int i=0;i<5;i++){ if(x->c[i]!=y->c[i])return x->c[i]-y->c[i];} return 0;}
static void canon(Ev*e){ // sort columns ascending with values
  for(int i=1;i<5;i++){int16_t cc=e->c[i];uint8_t vv=e->v[i];int j=i-1;while(j>=0&&e->c[j]>cc){e->c[j+1]=e->c[j];e->v[j+1]=e->v[j];j--;}e->c[j+1]=cc;e->v[j+1]=vv;} }
static int cmpfull(const void*a,const void*b){const Ev*x=a,*y=b; for(int i=0;i<5;i++){ if(x->c[i]!=y->c[i])return x->c[i]-y->c[i]; } for(int i=0;i<5;i++){ if(x->v[i]!=y->v[i])return x->v[i]-y->v[i]; } return x->row-y->row;}
static int checkagainst(){ // compare current lists to fullscan
  Vec U2=U,H2=Hs; int *cu=cellU; // save
  Vec nU={0},nH={0}; U=nU;Hs=nH; cellU=calloc((size_t)N*K,sizeof(int));
  fullscan();
  Vec A1[2]={U2,H2},A2[2]={U,Hs}; int bad=0;
  for(int z=0;z<2;z++){ for(int i=0;i<A1[z].n;i++)canon(&A1[z].a[i]); for(int i=0;i<A2[z].n;i++)canon(&A2[z].a[i]);
    qsort(A1[z].a,A1[z].n,sizeof(Ev),cmpfull);qsort(A2[z].a,A2[z].n,sizeof(Ev),cmpfull);
    if(A1[z].n!=A2[z].n){bad++;fprintf(stderr,"CHECK size mismatch z=%d inc %d full %d\n",z,A1[z].n,A2[z].n);}
    else for(int i=0;i<A1[z].n;i++) if(cmpfull(&A1[z].a[i],&A2[z].a[i])){bad++;fprintf(stderr,"CHECK mismatch z=%d i=%d\n",z,i);break;} }
  int cb=memcmp(cu,cellU,sizeof(int)*N*K); if(cb){bad++;fprintf(stderr,"CHECK cellU mismatch\n");}
  free(U.a);free(Hs.a);free(cellU); U=U2;Hs=H2;cellU=cu; return bad; }
static void save(const char*fn){FILE*o=fopen(fn,"w");for(int r=0;r<N;r++){for(int c=0;c<K;c++)fprintf(o,"%d%c",A[r][c],c==K-1?'\n':' ');}fclose(o);}
int main(int argc,char**argv){
  FILE*f=fopen(argv[1],"r"); rs=atoll(argv[2])*2654435761ULL+88172645463325252ULL; double T=atof(argv[3]); long maxflips=atol(argv[4]); char*out=argv[5]; int trunc=argc>6?atoi(argv[6]):0;
  if(getenv("THREADS"))THREADS=atoi(getenv("THREADS")); int CHECK=getenv("CHECK")?atoi(getenv("CHECK")):0; long MAXIT=getenv("MAXIT")?atol(getenv("MAXIT")):(1L<<60);
  static char line[20000]; N=0;K=0;
  int NR=getenv("NROWS")?atoi(getenv("NROWS")):9999; while(N<NR&&fgets(line,sizeof line,f)){int k=0;uint8_t row[192];for(char*p=line;*p;p++)if(*p=='0'||*p=='1')row[k++]=*p-'0'; if(!k)continue; if(!K)K=k; if(trunc&&K>trunc)K=trunc; for(int c=0;c<K;c++)setbit(N,c,row[c]); N++;}
  fclose(f);
  for(int i=0;i<192;i++)for(int w=0;w<CW;w++){uint64_t m=0;for(int b=0;b<64;b++)if(w*64+b>i&&w*64+b<K)m|=1ULL<<b;gt[i][w]=m;}
  cellU=calloc((size_t)N*K,sizeof(int));
  fprintf(stderr,"N=%d K=%d threads=%d\n",N,K,THREADS);
  struct timespec t0;clock_gettime(CLOCK_MONOTONIC,&t0);
  fullscan(); {struct timespec t1;clock_gettime(CLOCK_MONOTONIC,&t1);fprintf(stderr,"fullscan wall=%.1f holes=%d unique=%d\n",(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)*1e-9,Hs.n,U.n);}
  int best=Hs.n; long it=0,acc=0; static int tabu[MAXN][192]; char fn[600];
  while(Hs.n>0 && acc<maxflips && it<MAXIT){
    it++;
    Ev h=Hs.a[rnd()%Hs.n];
    int bd=1<<30,br=-1,bj=-1,nb=0;
    for(int r=0;r<N;r++){
      int diff=-1,nd=0;for(int i=0;i<5;i++)if(A[r][h.c[i]]!=h.v[i]){nd++;diff=i;if(nd>1)break;}
      if(nd!=1)continue; int c=h.c[diff]; if(tabu[r][c]>it)continue;
      int gain=0; int nv=1-A[r][c];
      for(int i=0;i<Hs.n;i++){Ev*e=&Hs.a[i];int j=-1;for(int q=0;q<5;q++)if(e->c[q]==c){j=q;break;} if(j<0)continue;
        int ok=1;for(int q=0;q<5;q++){int val=(q==j)?nv:A[r][e->c[q]];if(val!=e->v[q]){ok=0;break;}} if(ok)gain++;}
      int d=cellU[r*K+c]-gain;
      if(d<bd){bd=d;br=r;bj=diff;nb=1;} else if(d==bd){nb++;if(rnd()%nb==0){br=r;bj=diff;}}
    }
    if(br<0)continue;
    if(bd>0 && ur()>exp(-bd/T)) continue;
    int c=h.c[bj]; flip(br,c); tabu[br][c]=it+50+rnd()%50; acc++;
    if(CHECK && (acc<=CHECK)){int bad=checkagainst(); fprintf(stderr,"flip %ld (%d,%d) holes %d check bad=%d\n",acc,br,c,Hs.n,bad); if(bad)return 1;}
    if(Hs.n<best){best=Hs.n; struct timespec t1;clock_gettime(CLOCK_MONOTONIC,&t1);fprintf(stderr,"acc=%ld it=%ld wall=%.1f holes=%d unique=%d\n",acc,it,(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)*1e-9,Hs.n,U.n); snprintf(fn,sizeof fn,"%s_best.txt",out); save(fn);}
    if(acc%200==0){struct timespec t1;clock_gettime(CLOCK_MONOTONIC,&t1);fprintf(stderr,"progress acc=%ld it=%ld wall=%.1f holes=%d best=%d\n",acc,it,(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)*1e-9,Hs.n,best);}
  }
  snprintf(fn,sizeof fn,"%s_end.txt",out); save(fn);
  fprintf(stderr,"end acc=%ld it=%ld holes=%d best=%d\n",acc,it,Hs.n,best);
  if(Hs.n==0){snprintf(fn,sizeof fn,"%s_%d.txt",out,N);save(fn);printf("ZERO N=%d written %s\n",N,fn);}
  return 0;}
